#!/usr/bin/env bash
# Generate .clangd configuration with Lean 4 toolchain sysroot includes
# Usage: bash gen_clangd.sh [PROJECT_DIR]

set -euo pipefail
TARGET_DIR="${1:-.}"
cd "$TARGET_DIR" || exit 1

PREFIX=$(lake env lean --print-prefix 2>/dev/null)
if [ -z "$PREFIX" ] || [ ! -d "$PREFIX/include" ]; then
  echo "Error: Could not resolve Lean toolchain prefix via lake env lean --print-prefix"
  exit 1
fi

cat << CLANGD_EOF > .clangd
# Auto-generated by gen_clangd.sh for Lean 4 C/C++ FFI and IR analysis
CompileFlags:
  Add:
    - "-I$PREFIX/include"
    - "-isystem"
    - "$PREFIX/include/clang"
    - "-Wno-unused-parameter"
    - "-Wno-unused-label"
    - "-fvisibility=hidden"
CLANGD_EOF

echo "Generated .clangd configuration for Lean sysroot: $PREFIX/include"
